  padding: 0 50px 100px;
  color: var(--editor-color);
}
.mu-container p,
.mu-container blockquote,
.mu-container ul,
.mu-container ol,
.mu-container dl,
.mu-container table,
.mu-container figure:not(.mu-table) {
