  background: var(--selection-color);
}
.mu-table-picker-cell:last-of-type {
  margin-right: 0;
}
.mu-table-picker .footer {
  display: flex;
  justify-content: space-around;
  padding: 10px 0 0;
  color: var(--editor-color);
  text-align: center;
  border-top: 1px solid var(--float-border-color);
}
.mu-table-picker .footer input {
  box-sizing: border-box;
  width: 30px;
  height: 20px;
  padding: 0;
  color: var(--editor-color);
  text-align: center;
  background: var(--float-border-color);
  border: none;
  border-radius: 3px;
  outline: none;
}
.mu-table-picker .footer button {
  height: 20px;
  color: #fff;
  line-height: 20px;
  background: var(--theme-color);
  border: none;
  border-radius: 3px;
  outline: none;
  cursor: pointer;
}

/* ../marktext/packages/muya/src/ui/tableColumnToolbar/index.css */
.mu-float-wrapper.mu-table-column-tools-container {
  overflow: visible;
  border-radius: 2px;
}
.mu-table-column-tools {
  width: 160px;
  height: 24px;
}
.mu-table-column-tools ul,
.mu-table-column-tools li {
  margin: 0;
  padding: 0;
}
.mu-table-column-tools ul {
  display: flex;
  padding: 0 5px;
}
.mu-table-column-tools li.item {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-around;
  width: 24px;
  height: 24px;
  list-style: none;
  cursor: pointer;
}
.mu-table-column-tools li.item:hover {
  background: var(--float-hover-color);
}
.mu-table-column-tools li.item:last-of-type {
  margin-left: 6px;
}
.mu-table-column-tools li.item:last-of-type::before {
  position: absolute;
  top: 5px;
  left: -3px;
  width: 1px;
  height: 14px;
  background: var(--editor-color-10);
  content: "";
}
.mu-table-column-tools li.item .icon-wrapper {
  display: flex;
  width: 14px;
  height: 14px;
}
.mu-table-column-tools li.item .icon-wrapper i.icon {
  position: relative;
  display: inline-block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  color: var(--icon-color);
  transition: all 0.25s ease-in-out;
}
.mu-table-column-tools li.item .icon-wrapper i.icon > i[class^=icon-] {
  position: relative;
  left: -14px;
  display: inline-block;
  width: 100%;
  height: 100%;
  filter: drop-shadow(14px 0 currentcolor);
}
.mu-table-column-tools li.item.active .icon-wrapper i.icon {
  color: var(--theme-color);
}
.mu-table-column-tools li.item.delete .icon-wrapper i.icon {
  color: var(--delete-color);
}

/* ../marktext/packages/muya/src/ui/tableDragBar/index.css */
.mu-table-drag-container {
  border: none;
  box-shadow: none;
  cursor: pointer;
}
.mu-table-drag-bar[data-drag=bottom] {
  box-sizing: border-box;
  width: 24px;
  height: 10px;
  border: 1px solid var(--editor-color-30);
  border-radius: 5px;
}
.mu-table-drag-bar[data-drag=right] {
  box-sizing: border-box;
  width: 10px;
  height: 24px;
  border: 1px solid var(--editor-color-30);
  border-radius: 5px;
}
.mu-table-drag-bar::before,
.mu-table-drag-bar::after {
  position: absolute;
  display: block;
  width: 4px;
  height: 4px;
  background: var(--icon-color);
  border-radius: 2px;
  content: "";
}
.mu-table-drag-bar[data-drag=bottom]::before {
  top: 3px;
  left: 4px;
}
.mu-table-drag-bar[data-drag=bottom]::after {
  top: 3px;
  right: 4px;
}
.mu-table-drag-bar[data-drag=right]::before {
  top: 4px;
  right: 3px;
}
.mu-table-drag-bar[data-drag=right]::after {
  right: 3px;
  bottom: 4px;
}
.mu-cell-transform {
  transition: transform 0.3s ease-in-out;
}
.mu-drag-cell {
  z-index: 1;
  background: var(--float-bg-color);
  opacity: 0.7;
  transition: left 0.3s ease-in-out, bottom 0.3s ease-in-out;
}
.mu-drag-cell.ag-drag-right {
  left: -6px;
}
.mu-drag-cell.ag-drag-bottom {
  bottom: -6px;
}

/* ../marktext/packages/muya/src/ui/tableRowColumMenu/index.css */
.mu-table-bar-tools {
  min-width: 120px;
}
.mu-table-bar-tools ul,
.mu-table-bar-tools li {
  margin: 0;
  padding: 0;
}
.mu-table-bar-tools ul {
  padding: 5px 0;
}
.mu-table-bar-tools li.item {
  position: relative;
  height: 25px;
  padding: 0 8px;
  color: var(--editor-color);
  font-size: 13px;
  line-height: 25px;
  white-space: nowrap;
  cursor: pointer;
}
.mu-table-bar-tools li.item[data-label=remove] {
  margin-top: 10px;
}
.mu-table-bar-tools li.item[data-label=remove]::before {
  position: absolute;
  top: -5px;
  left: 8px;
  display: block;
  width: calc(100% - 16px);
  height: 1px;
  background: var(--editor-color-04);
  content: "";
}
.mu-table-bar-tools li.item:hover {
  background-color: var(--float-hover-color);
}

/* ../marktext/packages/muya/src/ui/tooltip/index.css */
.mu-tooltip {
  position: absolute;
  z-index: 1000;
  box-sizing: border-box;
  padding: 5px 7px;
  color: var(--editor-color);
  font-size: 12px;
  background: var(--float-bg-color);
  border: 1px solid var(--float-border-color);
  border-radius: 5px;
  box-shadow: 0 4px 8px 0 var(--float-border-color);
  opacity: 0;
  transition: opacity 0.2s ease-in;
}
.mu-tooltip.active {
  transform: translateY(-5px);
  opacity: 1;
}
.mu-tooltip::after {
  position: absolute;
  top: -2px;
  left: 50%;
  display: block;
  width: 8px;
  height: 8px;
  background: inherit;
  border: 1px solid var(--float-border-color);
  border-right: none;
  border-bottom: none;
  transform: rotate(45deg) translateX(-50%);
  content: "";
}

